def valid(order, deps):
    pos = {t: i for i, t in enumerate(order)}
    return sorted(order) == sorted(deps) and all(pos[u] < pos[t] for t, ups in deps.items() for u in ups)

assert topological_order({}) == []
d1 = {"publish": {"check"}, "check": {"revenue"}, "revenue": {"orders", "fx"}, "orders": set(), "fx": set()}
assert valid(topological_order(d1), d1), topological_order(d1)
d2 = {"a": set(), "b": {"a"}, "c": {"b"}, "d": {"a"}, "e": {"c", "d"}}
assert valid(topological_order(d2), d2)
for bad in ({"a": {"b"}, "b": {"a"}}, {"a": {"a"}}, {"x": set(), "a": {"c"}, "b": {"a"}, "c": {"b"}}):
    try:
        topological_order(bad)
    except ValueError:
        pass
    else:
        raise AssertionError(f"no ValueError for the cycle in {bad}")
import random
rng = random.Random(1)
names = [f"task{i}" for i in range(300)]
rng.shuffle(names)                       # dependencies only on earlier names in this list: no cycle
big = {names[i]: {names[j] for j in rng.sample(range(i), min(i, 3))} for i in range(300)}
assert valid(topological_order(big), big)

exercises.reference:
from collections import deque

def topological_order(deps):
    """deps maps each task to the set of tasks it depends on (every task is a key).
    Return a list of all the tasks in which each task comes after all its dependencies.
    Raise ValueError if the dependencies contain a cycle."""
    waiting = {t: len(ups) for t, ups in deps.items()}
    downstream = {t: [] for t in deps}
    for t, ups in deps.items():
        for u in ups:
            downstream[u].append(t)
    ready = deque(t for t, n in waiting.items() if n == 0)
    order = []
    while ready:
        t = ready.popleft()
        order.append(t)
        for d in downstream[t]:
            waiting[d] -= 1
            if waiting[d] == 0:
                ready.append(d)
    if len(order) < len(deps):
        raise ValueError("the dependencies contain a cycle")
    return order

exercises.solution:
Kahn's algorithm keeps a queue of ready tasks:

```python
from collections import deque

def topological_order(deps):
    waiting = {t: len(ups) for t, ups in deps.items()}
    downstream = {t: [] for t in deps}
    for t, ups in deps.items():
        for u in ups:
            downstream[u].append(t)
    ready = deque(t for t, n in waiting.items() if n == 0)
    order = []
    while ready:
        t = ready.popleft()
        order.append(t)
        for d in downstream[t]:
            waiting[d] -= 1
            if waiting[d] == 0:
                ready.append(d)
    if len(order) < len(deps):
        raise ValueError("the dependencies contain a cycle")
    return order
```

Each task enters the queue once and each dependency edge is processed once, so the time is $O(V + E)$. Sorting the names, as the starter does, is not enough: in the first test, `check` sorts before `revenue` but depends on it. Python's standard library offers the same algorithm as `graphlib.TopologicalSorter`, which also raises an error on cycles.

exercises.reference:
def to_rerun(deps, status, changed):
    """deps: task -> set of upstream tasks (every task is a key).
    status: task -> "success", "failed" or "upstream_failed", for one day's run.
    changed: the set of tasks whose code has changed since that run.
    Return the sorted list of tasks to run again: every task that did not succeed,
    and every changed task together with everything downstream of it."""
    downstream = {t: set() for t in deps}
    for t, ups in deps.items():
        for u in ups:
            downstream[u].add(t)
    todo = {t for t, s in status.items() if s != "success"} | set(changed)
    stack = list(changed)
    while stack:                                  # everything reachable from a changed task
        t = stack.pop()
        for d in downstream[t]:
            if d not in todo:
                todo.add(d)
                stack.append(d)
    return sorted(todo)

exercises.solution:
Invert the edges, then do a graph search from the changed tasks:

```python
def to_rerun(deps, status, changed):
    downstream = {t: set() for t in deps}
    for t, ups in deps.items():
        for u in ups:
            downstream[u].add(t)
    todo = {t for t, s in status.items() if s != "success"} | set(changed)
    stack = list(changed)
    while stack:
        t = stack.pop()
        for d in downstream[t]:
            if d not in todo:
                todo.add(d)
                stack.append(d)
    return sorted(todo)
```

An iterative search avoids Python's recursion limit on the 2,000-task chain in the tests. Changing `stage_orders` forces `daily_revenue`, `ml_features`, `check_revenue` and `publish` to run again, but not the extracts: their outputs are unchanged. This is the same graph search a lineage tool performs for impact analysis, as <LessonLink slug="data-quality-and-governance">Data quality and governance</LessonLink> discusses; dbt exposes it as a selector (`stage_orders+` means a model and everything downstream of it).
